    /// Encodes the packet payload into a game frame: `[0xFE] [Length] [Header] [Body]`.
    pub fn encode_game_frame<B: bytes::BufMut>(
        &self,
        buf: &mut B,
        from_subclient: u32,
        to_subclient: u32,
    ) -> Result<(), std::io::Error> {
        buf.put_u8(GAME_PACKET_ID);
        self.encode_inner(buf, from_subclient, to_subclient)
    }
    /// Fast path for encoding a game frame into `BytesMut`.
    pub fn encode_game_frame_bytes_mut(
        &self,
        buf: &mut bytes::BytesMut,
        from_subclient: u32,
        to_subclient: u32,
    ) -> Result<(), std::io::Error> {
        bytes::BufMut::put_u8(buf, GAME_PACKET_ID);
        self.encode_inner_bytes_mut(buf, from_subclient, to_subclient)
    }
    /// Keeps each packet's decode temporaries out of the shared dispatch
    /// stack frame. Inlining the largest codecs here makes even tiny
    /// packets pay for Windows stack probes and cross-variant spills.
    #[inline(never)]
    fn decode_payload<T, B>(
        buf: &mut B,
        args: T::Args,
    ) -> Result<Self, crate::bedrock::error::DecodeError>
    where
        T: crate::bedrock::codec::BedrockCodec + Into<Self>,
        B: bytes::Buf,
    {
        Self::decode_small_payload::<T, B>(buf, args)
    }
    #[inline]
    fn decode_small_payload<T, B>(
        buf: &mut B,
        args: T::Args,
    ) -> Result<Self, crate::bedrock::error::DecodeError>
    where
        T: crate::bedrock::codec::BedrockCodec + Into<Self>,
        B: bytes::Buf,
    {
        let packet = T::decode(buf, args)?;
        if buf.has_remaining() {
            return Err(crate::bedrock::error::DecodeError::TrailingPacketBytes {
                remaining: buf.remaining(),
            });
        }
        Ok(packet.into())
    }
    /// Decodes a batch entry from the provided buffer: `[Length] [Header] [Body]`.
    /// Returns the header and the packet payload.
    ///
    /// Returns `DecodeError::TrailingPacketBytes` if the decoded packet
    /// does not consume its entire declared payload. Bytes belonging to
    /// subsequent batch entries are not part of this check.
    pub fn decode_inner<B: bytes::Buf>(
        buf: &mut B,
        _args: McpePacketArgs,
    ) -> Result<(GameHeader, Self), crate::bedrock::error::DecodeError> {
        let declared_len = wire::read_var_u32(buf)? as usize;
        if buf.remaining() < declared_len {
            return Err(crate::bedrock::error::DecodeError::PacketLengthExceeded {
                declared: declared_len,
                available: buf.remaining(),
            });
        }
        let mut payload_buf = bytes::Buf::take(&mut *buf, declared_len);
        Self::decode_bounded_payload(&mut payload_buf, _args)
    }
    #[inline]
